WITH valid AS (SELECT id, event_type, event_time, duration_sec, TRIM(page) AS clean_page, CASE WHEN page = '/search' THEN 1 ELSE 0 END AS is_search, COALESCE(page, 'OTHER') AS page_filled FROM web_events WHERE page IS NOT NULL), prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_event_time FROM valid), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, event_type, CASE WHEN is_search >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_search_tier, COUNT(*) AS cnt, MIN(prev_event_time) AS first_seen, SIZE(COLLECT_SET(event_type)) AS num_event_types, COUNT_IF(event_type = 'purchase') AS purchase_events, COUNT(*) AS row_count, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min FROM islands GROUP BY CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END, event_type, CASE WHEN is_search >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING purchase_events < 1 ORDER BY is_search_tier;
